// `citado_id` (snake) e o nome que vem do RETURNING do Postgres.
const citadoId = (itens.map(m => m.citado_id).filter(Boolean)[0]) || null;
// O imovel da mensagem que ele marcou, quando a gente consegue casar.
const codigoCitado = (itens.map(m => m.codigo_citado).filter(Boolean)[0]) || null;
// Uniao dos codigos que ele escreveu, sem os valores.
const codigosDele = [...new Set(itens.flatMap(m => m.codigos_citados || []))];
return [{ json: { pedeUnidade: pedeUnidade, citadoId: citadoId, codigoCitado: codigoCitado, codigosDele: codigosDele, telefone: itens[0].telefone, nome: nomeItem ? nomeItem.nome : null, pedeVisita: pedeVisita, focoAviso: focoAviso, vaoSairFotos: vaoSairFotos, negocioPedido: negocioPedido, opcoesCitacao: (itens.map(m => m.opcoes_citacao).filter(Boolean)[0]) || null, nomePessoa: (itens.map(m => m.nome_pessoa).filter(Boolean)[0]) || null, texto: texto, textoCru: textoCru, citado: citado, naoTexto: nt, ids: itens.map(m => m.id), qtd: itens.length } }];

const w = $('Webhook').first().json.body || {};
// Mesma parede do "Detectar imagem" (16/09): audio que SAI daqui nao volta
// para ser transcrito. Nunca quebrou nada porque a resposta do Whisper nao tem
// campo `id`, mas transcrever o proprio audio e gasto sem uso.
if (w.isGroup || w.isNewsletter || w.broadcast || w.isStatusReply) return [];
if (w.type !== 'ReceivedCallback') return [];
if (w.fromMe || w.fromApi) return [];
const a = w.audio || {};
const url = a.audioUrl || '';
if (!url) return [];
const seg = Number(a.seconds || 0);
return [{ json: { audio_url: url, seg: seg, longo: seg > 180, telefone: w.phone, nome: w.senderName } }];

// LIDO de `regex_liberar.js` pelo patch -- nao editar aqui.
const TAXA_CODIGO = /^(\d{3,5})\s*[-–—:,]?\s*([^\d]{2,40})$/;
const FALA_DE_TAXA = /\b(tx|taxa|condominio|condomínio|cond)\b/i;
const FALA_DE_INCLUSAO = /\b(inclus[ao]|inclu[íi]d[ao]|inclui)\b/i;
const NEGA = /\b(nao|não|sem)\b/i;

function ehComandoDeTaxa(texto) {
  const m = TAXA_CODIGO.exec(String(texto || ''));
  if (!m) return false;
  const resto = m[2];
  if (!FALA_DE_TAXA.test(resto)) return false;
  return FALA_DE_INCLUSAO.test(resto) || NEGA.test(resto);
}

const VOC = '(?:@?nay\\b[\\s,;:.!?-]*)?';

const V_DESCARTA =
  '(?:descarta|descartar|descarte|esquece|esquecer|esqueca|esqueça|' +
  'apaga|apagar|cancela|cancelar|ignora|ignorar)';

const V_RESPOSTA = '(?:resposta|responde|responder)';

const LIGACAO = '(?:\\s+a)?(?:\\s+pend[eê]ncias?)?';

const RE_RESPOSTA = new RegExp(
  '^\\s*' + VOC + V_RESPOSTA + LIGACAO + '\\s+(\\d{1,6})\\s+([\\s\\S]+?)\\s*$', 'i');

const RE_DESCARTA = new RegExp(
  '^\\s*' + VOC + V_DESCARTA + LIGACAO + '\\s+(\\d{1,6})\\s*$', 'i');

const RE_DESCARTA_TUDO = new RegExp(
  '^\\s*' + VOC + V_DESCARTA + '\\s+tudo\\s*$', 'i');

const RE_DESCARTA_TUDO_SIM = new RegExp(
  '^\\s*' + VOC + V_DESCARTA + '\\s+tudo\\s+sim\\s*$', 'i');

const RE_LISTAR = new RegExp(
  '^\\s*' + VOC + '(?:pend[eê]ncias?|pendentes)\\s*$', 'i');

function ehComandoDePendencia(t) {
  const s = String(t || '');
  return RE_DESCARTA_TUDO_SIM.test(s) || RE_DESCARTA_TUDO.test(s) ||
         RE_DESCARTA.test(s) || RE_RESPOSTA.test(s) || RE_LISTAR.test(s);
}

function interpretarPendencia(t) {
  const s = String(t || '');
  let m;
  if (RE_DESCARTA_TUDO_SIM.test(s)) return { acao: 'DESCARTAR TUDO SIM', p_id: null, p_texto: null };
  if (RE_DESCARTA_TUDO.test(s)) return { acao: 'DESCARTAR TUDO', p_id: null, p_texto: null };
  m = s.match(RE_RESPOSTA);
  if (m) return { acao: 'RESPOSTA', p_id: parseInt(m[1], 10), p_texto: m[2].trim() };
  m = s.match(RE_DESCARTA);
  if (m) return { acao: 'DESCARTAR', p_id: parseInt(m[1], 10), p_texto: null };
  if (RE_LISTAR.test(s)) return { acao: 'PENDENCIAS', p_id: null, p_texto: null };
  return null;
}


// ===== NAI: o caminho sai do CABECALHO (Abrir turno), nunca do texto solto.
function ehComandoAntigo(t) {
  return ehComandoDePendencia(t)
    || /^\s*(?:@?nay\b[\s,;:.!?-]*)?(envi|m[a]?nd|repass|encaminh|mostr|post|public|dispar|solt)(?:a|ar|e|ei|ou|o)?\b([\s\S]*)(?:\bpara\b|\bpra\b|\bpro\b|\bp\/)\s*([\s\S]+?)\s*$/i.test(t)
    || /^(@?NAY\b[\s,:;.!\-]*)?((POSTA|POSTAR|PUBLICA|PUBLICAR|DISPARA|DISPARAR|SOLTA|TIRA|TIRAR|REMOVE|REMOVER|RETIRA|RETIRAR|VENDEU|VENDIDO|VENDIDA|ALUGOU|ALUGADO|ALUGADA|VAGAS|VAGA|LISTA)\b|(MANDA|MANDAR|MANDE|ENVIA|ENVIAR|ENVIE)\s+(AS?\s+|OS?\s+)?(LISTA|APARTAMENTOS?|APTOS?|COBERTURAS?|FLATS?|CASAS?|SOBRADOS?|SALAS?|LOJAS?|LOTES?|TERRENOS?)\b)/i.test(t)
    || /^(?:@?NAY\b[\s,:;.!\-]*)?(\d{3,5})\s*[-–—:,]?\s*(?:JA|JÁ)?\s*(VENDEU|VENDIDO|VENDIDA|ALUGOU|ALUGADO|ALUGADA)\b/i.test(t)
    || ehComandoDeTaxa(t);
}
const j = $('Juntar mensagens').first().json;
let cab = {};
try { cab = $('Abrir turno').first().json.cab || {}; } catch (e) { cab = {}; }
if (cab.ok !== true) return [];                       // sem cabecalho, nada sai
const papel = cab.papel;
const t = String(cab.texto || '').trim();
const envelope = String(j.texto || '').trim();
if (papel === 'tel') {
  // Comando da NAI (VISITAS, VISITA N, ACESSO, ASSUMIR, DEVOLVER e, desde
  // 15/09, AGENDA DE VISITAS). Quem decide e o banco, em `cab.comando_nai`;
  // a regex abaixo fica como reserva para cabecalho antigo.
  if (cab.comando_nai === true) return [{ json: { rota: 'tel_nai' } }];
  if (/^\s*(@?nay[\s,:;.!-]*)?(visitas\s*$|visita\s+#?\d+\s+\S|acesso\s+\d{3,5}\s+\S|(assumir|devolver)\s+\S)/i.test(t)) return [{ json: { rota: 'tel_nai' } }];
  if (ehComandoAntigo(t)) return [{ json: { rota: cab.teste === true ? 'aviso_teste' : 'tel_antigo' } }];
  return envelope ? [{ json: { rota: 'agente' } }] : [];
}
if (cab.pausado !== false) return [];                  // pausada (ou sem saber): silencio
if (papel === 'proprietario') return t ? [{ json: { rota: 'proprietario' } }] : [];
if (papel === 'motoboy') return t ? [{ json: { rota: 'motoboy' } }] : [];
// corretor -- o porteiro, que falha FECHADO
// A PORTA primeiro (Tel, 15/09): com a regra publica ligada, quem decide e
// `nai_deve_atender`, no banco. false = silencio; true = atende mesmo sem
// estar em `corretores` (gente nova que chega do grupo perguntando de
// imovel). Indefinido = regra desligada, e vale o porteiro de sempre.
if (cab.atende === false) return [];
if (cab.atende !== true && cab.aprovado !== true) return cab.primeira_vez === true ? [{ json: { rota: 'cortesia' } }] : [];
// NUMERO SOLTO: so e codigo de imovel quando ela NAO acabou de perguntar o
// valor. Em 13/09 ela perguntou a faixa de preco, ele respondeu "3500" e
// levou "nao achei nenhum imovel com o codigo 3500".
if (/^\d{3,5}$/.test(t) && cab.esperando_valor !== true) return [{ json: { rota: 'codigo', codigo: parseInt(t, 10) } }];
if (!envelope) return [];
return [{ json: { rota: 'agente' } }];

const r = $input.first().json;
const saida = String(r.output || r.text || '');
const j = $('Juntar mensagens').first().json;
const escreveu = String(j.texto || '');
// O que sai daqui como `escreveu` alimenta `nay_deve_mandar_fotos`.
// Tem que ser a fala DELE, nunca o envelope que este fluxo escreveu.
// O fallback existe para o caso de `Juntar mensagens` ser mais antigo
// que este no -- mas o guarda de comando acima continua lendo `escreveu`
// inteiro, senao um `textoCru` vazio abriria a porta que ele fecha.
const cru = String(j.textoCru !== undefined && j.textoCru !== null ? j.textoCru : (j.texto || ''));
const citou = String(j.citado || '');

// A QUARTA copia, a menos obvia: sem ela, "Nay envia as FOTOS do 5750
// pro Sergio" faz `pediuFoto` ler o texto do PROPRIO Tel e `solto`
// colher o 5750 -- as fotos sairiam para o chat dele tambem.
if (/^\s*(?:@?nay\b[\s,;:.!?-]*)?(envi|m[a]?nd|repass|encaminh|mostr|post|public|dispar|solt)(?:a|ar|e|ei|ou|o)?\b([\s\S]*)(?:\bpara\b|\bpra\b|\bpro\b|\bp\/)\s*([\s\S]+?)\s*$/i.test(escreveu)) {
  return [{ json: { texto: saida, codigo: '0', codigos: ['0'], escreveu: '' } }];
}

// TODOS os codigos que ela mandou, nao so o primeiro. Em 30/08 o Gustavo
// pediu "me passa as informacoes dos 3" -- ela mandaria os tres cards e so
// as fotos do primeiro sairiam.
const todos = [...saida.matchAll(/C[óo]digo:\s*(\d{3,5})/gi)].map(m => m[1]);

// Quando ela nao repetiu card nenhum, o imovel vem da citacao ou da fala
// dele. Numero colado a ponto ou virgula NAO conta: "valor: 900.000"
// virava codigo 900 (caso Sebastiana, 29/08).
const porRotulo = t => { const m = String(t).match(/C[óo]digo:\s*(\d{3,5})/i); return m ? m[1] : null; };
const solto = t => { const m = String(t).match(/(?<![\d.,])(\d{3,5})(?![\d.,])/); return m ? m[1] : null; };

// `codigosDele` vem de `nay_codigos_citados`, que tira os VALORES antes
// de procurar codigo -- "paga ate 4000" nao e o imovel 4000. O `solto()`
// cru fica so para a citacao, onde nao ha alternativa.
const dele = j.codigosDele || [];
const codigos = todos.length ? [...new Set(todos)]
  : [porRotulo(citou) || j.codigoCitado || porRotulo(escreveu) || dele[0] || solto(citou)].filter(Boolean);

return [{ json: {
  texto: saida,
  codigo: codigos[0] || '0',
  codigos: codigos.length ? codigos : ['0'],
  escreveu: cru
} }];

// CHECAGEM DUPLA DAS FOTOS (camada 2). A tabela nao tinha foto deste
// imovel: le o anuncio AO VIVO no site, como o publicador faz, e o banco
// grava antes de responder. Caso Regiane (01/09): 2014 com 24 fotos no
// anuncio e zero na tabela -- ela disse que nao tinha.
const r = $('Achar codigo na resposta').first().json;
const falt = (($input.first().json || {}).faltando || []).slice(0, 3);
const lidas = [];
for (const c of falt) {
  try {
    const html = String(await this.helpers.httpRequest({ method: 'GET', url: 'https://imobeasy.com/anuncios/' + c, timeout: 15000, json: false }) || '');
    const ini = html.indexOf('id="imagens"');
    if (ini < 0) continue;
    const fim = html.indexOf('</ul>', ini);
    const trecho = html.slice(ini, fim > ini ? fim : ini + 300000);
    const urls = [];
    for (const m of trecho.matchAll(/<a\b[^>]*>/g)) {
      const tag = m[0];
      if (!/class="[^"]*gallery-item/.test(tag)) continue;
      const h = tag.match(/href="([^"]+)"/);
      if (!h) continue;
      const u = h[1].startsWith('http') ? h[1] : 'https://imobeasy.com' + h[1];
      if (!urls.includes(u)) urls.push(u);
    }
    lidas.push({ codigo: Number(c), urls });
  } catch (e) { /* site fora: segue; a guarda de promessa avisa o Tel */ }
}
return [{ json: { texto: r.texto, codigos: r.codigos, escreveu: r.escreveu, fotos_site: lidas } }];

